import{_ as t,C as r,o as l,c as s,a4 as i,j as d,E as c}from"./chunks/framework.BUqnS5H7.js";const v=JSON.parse('{"title":"线上问题案例集","description":"","frontmatter":{},"headers":[],"relativePath":"redis/04-high-availability/chapter-04-production-cases.md","filePath":"redis/04-high-availability/chapter-04-production-cases.md"}'),h={name:"redis/04-high-availability/chapter-04-production-cases.md"},o={"data-src-line":"9","data-src-file":"redis/04-high-availability/chapter-04-production-cases.md"};function n(p,a,f,u,b,g){const e=r("SvgDiagram");return l(),s("div",null,[a[0]||(a[0]=i('<h1 id="线上问题案例集" tabindex="-1" data-src-line="1" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">线上问题案例集 <a class="header-anchor" href="#线上问题案例集" aria-label="Permalink to &quot;线上问题案例集&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><p data-src-line="3" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">学完高可用三章，得到的是一套「现象 → 机制」的判断框架：为什么网络抖动一下服务就全挂、为什么 failover 明明成功了反而更糟、为什么一个节点的迁移能拖垮整个平台。这些看似玄学的线上现象，都能在复制同步、故障转移、集群机制里找到确定解释。本章收集 3 个国外知名企业的公开事故，每个案例回答三件事——现象是什么、根因落在哪个知识点、怎么处理和预防。</p></blockquote><h2 id="_1-知识地图-高可用能解释哪些生产问题" tabindex="-1" data-src-line="5" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">1. 知识地图：高可用能解释哪些生产问题 <a class="header-anchor" href="#_1-知识地图-高可用能解释哪些生产问题" aria-label="Permalink to &quot;1. 知识地图：高可用能解释哪些生产问题&quot;">​</a></h2><p data-src-line="7" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">3 个案例的根因全部落在前三章的知识点上。先建立映射，再逐个展开：</p>',4)),d("p",o,[c(e,{src:"/redis/04-high-availability-chapter-04-production-cases-1.svg",alt:"高可用知识点与生产问题映射"})]),a[1]||(a[1]=i('<table tabindex="0"><thead data-src-line="11" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><tr data-src-line="11" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><th style="text-align:left;">知识点</th><th style="text-align:left;">生产问题</th><th style="text-align:left;">案例</th></tr></thead><tbody data-src-line="13" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><tr data-src-line="13" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><td style="text-align:left;">全量同步（<a href="./chapter-01-replication.html#full-sync">主从复制 §2</a>）</td><td style="text-align:left;">网络分区恢复后全量重同步压垮主库</td><td style="text-align:left;"><a href="#case-1">案例一</a></td></tr><tr data-src-line="14" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><td style="text-align:left;">故障转移（<a href="./chapter-02-sentinel.html#failover">哨兵 §4</a> / <a href="./chapter-03-cluster.html#cluster-failover">集群 §4.2</a>）</td><td style="text-align:left;">failover 后无 writable primary，全局不可写</td><td style="text-align:left;"><a href="#case-2">案例二</a></td></tr><tr data-src-line="15" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><td style="text-align:left;">故障转移缺陷（<a href="./chapter-02-sentinel.html#failover">哨兵 §4</a>）</td><td style="text-align:left;">节点迁移触发 failover 缺陷，级联故障</td><td style="text-align:left;"><a href="#case-3">案例三</a></td></tr></tbody></table><h2 id="case-1" tabindex="-1" data-src-line="17" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">2. 案例一：Twilio 主从网络分区，全量重同步压垮主库 <a class="header-anchor" href="#case-1" aria-label="Permalink to &quot;2. 案例一：Twilio 主从网络分区，全量重同步压垮主库 {#case-1}&quot;">​</a></h2><h3 id="_2-1-现象" tabindex="-1" data-src-line="19" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">2.1 现象 <a class="header-anchor" href="#_2-1-现象" aria-label="Permalink to &quot;2.1 现象&quot;">​</a></h3><p data-src-line="21" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">2013 年 7 月 18 日，Twilio 的计费系统出现故障。系统用 Redis 存储账户余额，一次网络分区把 Redis 主库与所有从库隔离。</p><p data-src-line="23" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">Twilio 没有提升新主库，写请求仍打到原主库——这本是保一致性的正确选择。但当主库重新对从库可见时，所有从库同时发起全量重同步（full resync），瞬间压垮主库，依赖 Redis 的服务全部失败。</p><p data-src-line="25" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">运维重启主库以应对高负载。重启后，主库加载了一份错误的配置文件，进入只读模式。所有账户余额显示为 0 且只读，每次 API 调用都触发自动充值，导致 1.1% 的客户在 40 分钟内被重复扣费。</p><h3 id="_2-2-根因" tabindex="-1" data-src-line="27" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">2.2 根因 <a class="header-anchor" href="#_2-2-根因" aria-label="Permalink to &quot;2.2 根因&quot;">​</a></h3><p data-src-line="29" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">两个机制叠加，缺一不可。</p><p data-src-line="31" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><strong>全量重同步风暴</strong>（见<a href="./chapter-01-replication.html#full-sync-storm">主从复制 §5.2</a>）。网络分区恢复后，所有从库的复制偏移量都已落后，同时向主库发起全量同步。全量同步要主库 fork 子进程生成 RDB 并逐个发送，N 个从库就是 N 份 RDB 同时生成与传输，主库既要处理正常请求又要承担 N 倍磁盘 IO 与网络带宽，瞬间过载。这正是<a href="./chapter-01-replication.html#full-sync">主从复制 §2</a> 讲的全量同步的 fork 代价被放大。</p><p data-src-line="33" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><strong>重启加载错误配置</strong>。主库重启后进入只读模式，业务层的自动充值逻辑把「余额 0 + 只读」误判为「需要充值」，反复扣款。这属于配置管理与业务侧幂等缺失，不是 Redis 本身的故障。</p><h3 id="_2-3-处理与预防" tabindex="-1" data-src-line="35" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">2.3 处理与预防 <a class="header-anchor" href="#_2-3-处理与预防" aria-label="Permalink to &quot;2.3 处理与预防&quot;">​</a></h3><ul data-src-line="37" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><li data-src-line="37" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">限制同时全量同步的从库数（哨兵 <code>parallel-syncs</code>），让重同步错峰执行，避免风暴。</li><li data-src-line="38" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">调大复制缓冲区（见<a href="./chapter-01-replication.html#repl-buffer">主从复制 §2.3</a>），减少全量同步的发生概率。</li><li data-src-line="39" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">配置文件版本化、变更走审批，重启前校验加载的是正确配置。</li><li data-src-line="40" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">业务侧的自动充值要有幂等与熔断，不能把「只读」或「余额 0」误判为「余额不足」。</li></ul><h2 id="case-2" tabindex="-1" data-src-line="42" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">3. 案例二：GitHub Actions 集群 failover 后无 writable primary <a class="header-anchor" href="#case-2" aria-label="Permalink to &quot;3. 案例二：GitHub Actions 集群 failover 后无 writable primary {#case-2}&quot;">​</a></h2><h3 id="_3-1-现象" tabindex="-1" data-src-line="44" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">3.1 现象 <a class="header-anchor" href="#_3-1-现象" aria-label="Permalink to &quot;3.1 现象&quot;">​</a></h3><p data-src-line="46" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">2026 年 3 月 5 日，GitHub Actions 出现服务降级。负责 workflow 任务队列协调的 Redis 集群做基础设施更新时，负载均衡器被引入错误配置，内部流量被路由到错误主机。</p><p data-src-line="48" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">随后 Redis 主节点发生自动 failover，failover「技术上完成」了，但一个潜伏的配置缺陷让集群在 failover 后没有任何可写的主节点。结果 95% 的 workflow 无法在 5 分钟内启动，平均延迟 30 分钟，10% 直接以基础设施错误失败。</p><h3 id="_3-2-根因" tabindex="-1" data-src-line="50" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">3.2 根因 <a class="header-anchor" href="#_3-2-根因" aria-label="Permalink to &quot;3.2 根因&quot;">​</a></h3><p data-src-line="52" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">根因是<a href="./chapter-02-sentinel.html#failover">故障转移 §4</a> 与<a href="./chapter-03-cluster.html#cluster-failover">集群模式 §4.2</a> 讲到的 failover 路径里的潜伏缺陷。</p><p data-src-line="54" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">failover 本身完成了，但完成的集群状态没有可写主节点——写请求全部失败。这是「故障转移路径里的 bug」：正常路径天天测，故障转移路径一年才走一次，配置从未在真实 failover 状态下验证过。</p><p data-src-line="56" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">次要因素：单一 Redis 集群承担所有 Actions 任务队列协调，没有按 workload 分片，一处失败即全局瘫痪。复制滞后也让 failover 无法干净完成，从库提升后继承的是不完整的队列状态。</p><h3 id="_3-3-处理与预防" tabindex="-1" data-src-line="58" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">3.3 处理与预防 <a class="header-anchor" href="#_3-3-处理与预防" aria-label="Permalink to &quot;3.3 处理与预防&quot;">​</a></h3><ul data-src-line="60" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><li data-src-line="60" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">failover 路径要在生产级负载下演练，不能只在安静维护窗口测试。</li><li data-src-line="61" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">队列按 runner 类型、组织层级分片，单分片失败只降级部分容量，而非 95% 全部阻塞。</li><li data-src-line="62" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">加死信队列，失败的分发任务落盘重试，而不是静默丢弃。</li><li data-src-line="63" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">预留足够的从库 headroom，让 failover 在负载下也能完成，而非只适用于空闲状态。</li></ul><h2 id="case-3" tabindex="-1" data-src-line="65" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">4. 案例三：Discord 节点迁移触发 failover 缺陷，级联故障 <a class="header-anchor" href="#case-3" aria-label="Permalink to &quot;4. 案例三：Discord 节点迁移触发 failover 缺陷，级联故障 {#case-3}&quot;">​</a></h2><h3 id="_4-1-现象" tabindex="-1" data-src-line="67" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">4.1 现象 <a class="header-anchor" href="#_4-1-现象" aria-label="Permalink to &quot;4.1 现象&quot;">​</a></h3><p data-src-line="69" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">2017 年 10 月 13 日 14:01，Google Cloud Platform 自动迁移了 Discord API 服务所用高可用集群中的一个 Redis 主节点。迁移导致该节点错误下线，迫使集群 rebalance，触发了 Discord API 处理 Redis failover 的已知缺陷。</p><p data-src-line="71" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">解决这个局部故障后，其他服务上未被注意的问题又引发了实时系统的级联故障。最终工程团队被迫完全重启服务，数百万客户端在 20 分钟内重连。</p><h3 id="_4-2-根因" tabindex="-1" data-src-line="73" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">4.2 根因 <a class="header-anchor" href="#_4-2-根因" aria-label="Permalink to &quot;4.2 根因&quot;">​</a></h3><p data-src-line="75" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">根因是<a href="./chapter-02-sentinel.html#failover">故障转移 §4</a> 的 failover 处理缺陷。</p><p data-src-line="77" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">主节点被云平台自动迁移、错误下线，集群进入 rebalance，failover 代码却有一个团队早就知道、但一直排在「未来几周」的缺陷，无法正确处理新主节点。局部故障由此放大。</p><p data-src-line="79" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">另一个被此次故障暴露的，是一个此前未知的缓存 misconfiguration，让部分节点的行为进一步恶化，最终把局部 API 故障拖成整个实时系统的级联失败。</p><h3 id="_4-3-处理与预防" tabindex="-1" data-src-line="81" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">4.3 处理与预防 <a class="header-anchor" href="#_4-3-处理与预防" aria-label="Permalink to &quot;4.3 处理与预防&quot;">​</a></h3><ul data-src-line="83" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><li data-src-line="83" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">已知的 failover 缺陷要提升修复优先级，不能长期挂在「未来几周」。</li><li data-src-line="84" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">加强 failover 相关信号的监控与告警，级联发生前留出排查时间。</li><li data-src-line="85" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">定期审查配置（尤其是边缘缓存规则），避免被突发故障连带暴露。</li></ul><h2 id="_5-小结与检查清单" tabindex="-1" data-src-line="87" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">5. 小结与检查清单 <a class="header-anchor" href="#_5-小结与检查清单" aria-label="Permalink to &quot;5. 小结与检查清单&quot;">​</a></h2><p data-src-line="89" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">3 个案例的共同点：问题不在 Redis 高可用机制本身，而在 failover 路径没被验证、全量同步没被限流、配置变更没被管控。</p><table tabindex="0"><thead data-src-line="91" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><tr data-src-line="91" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><th style="text-align:left;">检查项</th><th style="text-align:left;">说明</th></tr></thead><tbody data-src-line="93" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><tr data-src-line="93" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><td style="text-align:left;">限制同时全量同步的从库数</td><td style="text-align:left;">避免网络恢复后的重同步风暴</td></tr><tr data-src-line="94" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><td style="text-align:left;">failover 路径在负载下演练</td><td style="text-align:left;">不在安静窗口测试</td></tr><tr data-src-line="95" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><td style="text-align:left;">集群按 workload 分片</td><td style="text-align:left;">单点失败不放大为全局瘫痪</td></tr><tr data-src-line="96" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><td style="text-align:left;">配置文件版本化 + 变更审批</td><td style="text-align:left;">重启不加载错误配置</td></tr><tr data-src-line="97" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><td style="text-align:left;">业务侧幂等与熔断</td><td style="text-align:left;">「只读」不被误判为「余额不足」</td></tr></tbody></table><h2 id="_6-参考资料" tabindex="-1" data-src-line="99" data-src-file="redis/04-high-availability/chapter-04-production-cases.md">6. 参考资料 <a class="header-anchor" href="#_6-参考资料" aria-label="Permalink to &quot;6. 参考资料&quot;">​</a></h2><ul data-src-line="101" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><li data-src-line="101" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><a href="https://queue.acm.org/detail.cfm?id=2655736" target="_blank" rel="noreferrer">The Network is Reliable</a>（案例一，Twilio，Kyle Kingsbury）</li><li data-src-line="102" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><a href="https://www.githubstatus.com/incidents/g5gnt5l5hf56" target="_blank" rel="noreferrer">Multiple services are affected, service degradation</a>（案例二，GitHub）</li><li data-src-line="103" data-src-file="redis/04-high-availability/chapter-04-production-cases.md"><a href="https://discordstatus.com/incidents/qk9cdgnqnhcn" target="_blank" rel="noreferrer">Unavailable Guilds &amp; Connection Issues</a>（案例三，Discord）</li></ul>',37))])}const y=t(h,[["render",n]]);export{v as __pageData,y as default};
